Abstract base class

```python
# ❌ BAD Example - Violates OCP
class AreaCalculatorBad:
    def calculate_area(self, shape):
        if shape.type == "circle":
            return pi * shape.radius ** 2
        elif shape.type == "rectangle":
            return shape.width * shape.height
        elif shape.type == "triangle":
            return 0.5 * shape.base * shape.height
        # Adding new shape requires modifying this method! ❌

# ✅ GOOD Example - Follows OCP
class Shape(ABC):
    """Abstract base class"""
    @abstractmethod
    def area(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return pi * self.radius ** 2

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

class Triangle(Shape):
    def __init__(self, base, height):
        self.base = base
        self.height = height

    def area(self):
        return 0.5 * self.base * self.height

# Easy to extend - just add new class! ✅
class Pentagon(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return 1.72 * self.side ** 2
```

Base class for all birds Birds that can fly Birds that swim Duck can both fly and swim!

```python
# ❌ BAD Example - Violates LSP
class BirdBad:
    def fly(self):
        return "Flying in the sky!"

class SparrowBad(BirdBad):
    pass

class PenguinBad(BirdBad):
    def fly(self):
        raise Exception("Penguins can't fly!")  # Violates LSP! 💥

# ✅ GOOD Example - Follows LSP
class Bird:
    """Base class for all birds"""
    def move(self):
        return "Moving..."

class FlyingBird(Bird):
    """Birds that can fly"""
    def move(self):
        return "Flying in the sky! 🦅"

    def fly(self):
        return self.move()

class SwimmingBird(Bird):
    """Birds that swim"""
    def move(self):
        return "Swimming in water! 🐧"

    def swim(self):
        return self.move()

class Eagle(FlyingBird):
    pass

class Sparrow(FlyingBird):
    pass

class Penguin(SwimmingBird):
    pass

class Duck(FlyingBird, SwimmingBird):
    """Duck can both fly and swim!"""
    def move(self):
        return "Flying or Swimming! 🦆"

# Demo
print("\n🟢 Good Example (Substitutable objects):")
```

Fat interface - not all implementers need all methods Small, focused interface Small, focused interface Small, focused interface Implements only what it needs Only implements Workable - doesn't need eat/sleep

```python
# ❌ BAD Example - Violates ISP
class WorkerInterfaceBad(ABC):
    """Fat interface - not all implementers need all methods"""
    @abstractmethod
    def work(self):
        pass

    @abstractmethod
    def eat(self):
        pass

    @abstractmethod
    def sleep(self):
        pass

class HumanWorkerBad(WorkerInterfaceBad):
    def work(self):
        return "Human working..."

    def eat(self):
        return "Human eating..."

    def sleep(self):
        return "Human sleeping..."

class RobotWorkerBad(WorkerInterfaceBad):
    def work(self):
        return "Robot working..."

    def eat(self):
        raise NotImplementedError("Robots don't eat!")  # Forced to implement! ❌

    def sleep(self):
        raise NotImplementedError("Robots don't sleep!")  # Forced to implement! ❌

# ✅ GOOD Example - Follows ISP
class Workable(ABC):
    """Small, focused interface"""
    @abstractmethod
    def work(self):
        pass

class Eatable(ABC):
    """Small, focused interface"""
    @abstractmethod
    def eat(self):
        pass

class Sleepable(ABC):
    """Small, focused interface"""
    @abstractmethod
    def sleep(self):
        pass

class HumanWorker(Workable, Eatable, Sleepable):
    """Implements only what it needs"""
    def work(self):
        return "👷 Human working..."

    def eat(self):
        return "🍔 Human eating..."

    def sleep(self):
        return "😴 Human sleeping..."

class RobotWorker(Workable):
    """Only implements Workable - doesn't need eat/sleep"""
    def work(self):
        return "🤖 Robot working..."
```

Low-level module High-level module depends on low-level module directly Abstraction (interface) Low-level module implements abstraction Low-level module implements abstraction Low-level module implements abstraction

```python
# ❌ BAD Example - Violates DIP
class MySQLDatabaseBad:
    """Low-level module"""
    def connect(self):
        return "Connected to MySQL"

    def query(self, sql):
        return f"MySQL executing: {sql}"

class UserRepositoryBad:
    """High-level module depends on low-level module directly"""
    def __init__(self):
        self.db = MySQLDatabaseBad()  # Tight coupling! ❌

    def get_user(self, user_id):
        return self.db.query(f"SELECT * FROM users WHERE id={user_id}")

# ✅ GOOD Example - Follows DIP
class Database(ABC):
    """Abstraction (interface)"""
    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def query(self, sql):
        pass

class MySQLDatabase(Database):
    """Low-level module implements abstraction"""
    def connect(self):
        return "🔌 Connected to MySQL"

    def query(self, sql):
        return f"🐬 MySQL: {sql}"

class PostgreSQLDatabase(Database):
    """Low-level module implements abstraction"""
    def connect(self):
        return "🔌 Connected to PostgreSQL"

    def query(self, sql):
        return f"🐘 PostgreSQL: {sql}"

class MongoDatabase(Database):
    """Low-level module implements abstraction"""
    def connect(self):
        return "🔌 Connected to MongoDB"

    def query(self, sql):
        return f"🍃 MongoDB: {sql}"
```

Metaclass for Singleton pattern Database connection - only one instance needed

```python
class SingletonMeta(type):
    """Metaclass for Singleton pattern"""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            instance = super().__call__(*args, **kwargs)
            cls._instances[cls] = instance
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    """Database connection - only one instance needed"""
    def __init__(self):
        self.connection_count = 0
        print("🔌 Creating new database connection...")

    def connect(self):
        self.connection_count += 1
        return f"Connected (connection #{self.connection_count})"

    def query(self, sql):
        return f"Executing: {sql}"
```

Factory to create different notification types

```python
# Product interface
class Notification(ABC):
    @abstractmethod
    def send(self, message, recipient):
        pass

# Concrete products
class EmailNotification(Notification):
    def send(self, message, recipient):
        return f"📧 Email to {recipient}: {message}"

class SMSNotification(Notification):
    def send(self, message, recipient):
        return f"📱 SMS to {recipient}: {message}"

class PushNotification(Notification):
    def send(self, message, recipient):
        return f"🔔 Push to {recipient}: {message}"

class SlackNotification(Notification):
    def send(self, message, recipient):
        return f"💬 Slack to {recipient}: {message}"

# Factory
class NotificationFactory:
    """Factory to create different notification types"""

    @staticmethod
    def create_notification(notification_type: str) -> Notification:
        notifications = {
            'email': EmailNotification,
            'sms': SMSNotification,
            'push': PushNotification,
            'slack': SlackNotification
        }

        notification_class = notifications.get(notification_type.lower())
        if not notification_class:
            raise ValueError(f"Unknown notification type: {notification_type}")

        return notification_class()

# Demo
print("\n🔍 Testing Factory Pattern:")
factory = NotificationFactory()

notification_types = ['email', 'sms', 'push', 'slack']
for notif_type in notification_types:
    notification = factory.create_notification(notif_type)
    result = notification.send(f"Hello from {notif_type}!", "user@example.com")
    print(f"   {result}")

# Real-world example: Payment processing
print("\n💳 Real-world Example - Payment Processing:")
```

```python
class Payment(ABC):
    @abstractmethod
    def process_payment(self, amount):
        pass

class CreditCardPayment(Payment):
    def process_payment(self, amount):
        return f"💳 Processing ${amount} via Credit Card"

class PayPalPayment(Payment):
    def process_payment(self, amount):
        return f"🅿️ Processing ${amount} via PayPal"

class CryptoPayment(Payment):
    def process_payment(self, amount):
        return f"₿ Processing ${amount} via Cryptocurrency"

class PaymentFactory:
    @staticmethod
    def create_payment(payment_type: str) -> Payment:
        payments = {
            'credit_card': CreditCardPayment,
            'paypal': PayPalPayment,
            'crypto': CryptoPayment
        }
        return payments[payment_type.lower()]()

payment_factory = PaymentFactory()
for payment_type in ['credit_card', 'paypal', 'crypto']:
    payment = payment_factory.create_payment(payment_type)
    print(f"   {payment.process_payment(100)}")

print("\n✨ Factory Pattern makes it easy to add new types without changing client code!")

